    array("number" => 4, "name" => "Season 4", "rating" => 8.2, "episodes" => array(
        array("id" => "s4e1", "season" => 4, "number" => 1, "name" => "Do I Know You?", "airdate" => "22 Sep 2008", "runtime" => 30, "rating" => 8.2, "summary" => "As Stella responds to Ted's proposal, Barney realizes that he's in love with Robin.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/96/242479.jpg"),
