        array("id" => "s4e3", "season" => 4, "number" => 3, "name" => "I Heart NJ", "airdate" => "6 Oct 2008", "runtime" => 30, "rating" => 7.8, "summary" => "After inviting the gang to Stella's apartment in New Jersey, Ted tries to sell them on the perks of living in the suburbs until he learns that she expects him to move there after they're married.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/96/242482.jpg"),
        array("id" => "s4e4", "season" => 4, "number" => 4, "name" => "Intervention", "airdate" => "13 Oct 2008", "runtime" => 30, "rating" => 8.2, "summary" => "When Ted discovers that the gang ditched their plans to stage an intervention for his engagement to Stella, he is adamant that they go through with it anyway.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/242676.jpg"),
        array("id" => "s4e5", "season" => 4, "number" => 5, "name" => "Shelter Island", "airdate" => "20 Oct 2008", "runtime" => 30, "rating" => 8.3, "summary" => "After Stella and Ted make the spontaneous decision to get married in three days, the presence of their exes destroys what was to be the \"happiest day of their lives\".", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/242927.jpg"),
