        array("id" => "s4e7", "season" => 4, "number" => 7, "name" => "Not a Father's Day", "airdate" => "10 Nov 2008", "runtime" => 30, "rating" => 8.2, "summary" => "When Lily and Marshall contemplate making the life-changing decision to have a baby, Lily turns to Ted and Robin for advice and their very different points of view on the issue.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/242939.jpg"),
        array("id" => "s4e8", "season" => 4, "number" => 8, "name" => "Woooo!", "airdate" => "17 Nov 2008", "runtime" => 30, "rating" => 7.7, "summary" => "Robin rediscovers the \"Woo Girls,\" a group of single girls who like to go out and party. Meanwhile, Ted pitches Barney a design for his company's new headquarters.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243335.jpg"),
        array("id" => "s4e9", "season" => 4, "number" => 9, "name" => "The Naked Man", "airdate" => "24 Nov 2008", "runtime" => 30, "rating" => 8.9, "summary" => "After Ted walks into the apartment to find Robin's date sitting on the couch in the buff, the gang realizes this method might be the easiest way to get their dates into bed with them.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243336.jpg"),
        array("id" => "s4e10", "season" => 4, "number" => 10, "name" => "The Fight", "airdate" => "8 Dec 2008", "runtime" => 30, "rating" => 8.3, "summary" => "Ted tries to prove he's not pathetic for getting left at the altar, and Barney tries to impress Robin, who thinks fighting is sexy, by fighting with patrons who are sitting in their favorite booth.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243337.jpg"),
        array("id" => "s4e11", "season" => 4, "number" => 11, "name" => "Little Minnesota", "airdate" => "15 Dec 2008", "runtime" => 30, "rating" => 8.3, "summary" => "Ted turns into an overprotective, older brother by going out of his way to keep his sister out of trouble when she comes to visit him in New York. Meanwhile, Marshall and Robin bond when he introduces her to a Minnesota themed bar.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243341.jpg"),
        array("id" => "s4e12", "season" => 4, "number" => 12, "name" => "Benefits", "airdate" => "12 Jan 2009", "runtime" => 30, "rating" => 8.7, "summary" => "When Ted and Robin become \"friends with benefits\" to deal with conflicts they're having around the apartment, Barney tries to resolve the issues so they'll stop hooking up. Meanwhile, \"reality\" stars get too real for Marshall when they taunt him from the page…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243482.jpg"),
        array("id" => "s4e13", "season" => 4, "number" => 13, "name" => "Three Days of Snow", "airdate" => "19 Jan 2009", "runtime" => 30, "rating" => 8.2, "summary" => "When A blizzard shuts down the city, Marshall and Lily try to continue their longstanding airport reunion tradition while Ted and Barney volunteer to keep MacLaren's open so they can meet up with some college girls.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243485.jpg"),
        array("id" => "s4e14", "season" => 4, "number" => 14, "name" => "The Possimpible", "airdate" => "2 Feb 2009", "runtime" => 30, "rating" => 8.1, "summary" => "When Robin realizes that she only has four days to get a job or she will be deported back to Canada, she agrees to let Barney produce a video resume for her.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243658.jpg"),
        array("id" => "s4e15", "season" => 4, "number" => 15, "name" => "The Stinsons", "airdate" => "2 Mar 2009", "runtime" => 30, "rating" => 8.4, "summary" => "When the gang suspects that Barney has a girlfriend after he mysteriously leaves MacLaren's, they decide to follow him.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243659.jpg"),
