        array("id" => "s4e17", "season" => 4, "number" => 17, "name" => "The Front Porch", "airdate" => "16 Mar 2009", "runtime" => 30, "rating" => 8.5, "summary" => "When Karen finds another woman's earring in Ted's bed, he discovers that Lily planted it there on purpose, and that she secretly meddled in some of his previous relationships as well.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243683.jpg"),
        array("id" => "s4e18", "season" => 4, "number" => 18, "name" => "Old King Clancy", "airdate" => "23 Mar 2009", "runtime" => 30, "rating" => 7.7, "summary" => "When Goliath National Bank cancels plans to build their new headquarters that Ted was hired to design, Barney and Marshall concoct an elaborate lie to keep Ted from knowing he is out of a job.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243704.jpg"),
