        array("id" => "s4e20", "season" => 4, "number" => 20, "name" => "Mosbius Designs", "airdate" => "13 Apr 2009", "runtime" => 30, "rating" => 7.4, "summary" => "When Ted loses his job and decides to form his own architectural firm out of his apartment, he hires an intern to help get his company off the ground, but the intern gets too close for comfort with some of Ted's friends.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243822.jpg"),
        array("id" => "s4e21", "season" => 4, "number" => 21, "name" => "The Three Days Rule", "airdate" => "27 Apr 2009", "runtime" => 30, "rating" => 8.3, "summary" => "When Ted breaks Barney and Marshall's \"three days rule\" by having a \"text\" relationship with a girl he just met, they play a cruel joke on him by pretending to be her.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243829.jpg"),
        array("id" => "s4e22", "season" => 4, "number" => 22, "name" => "Right Place, Right Time", "airdate" => "4 May 2009", "runtime" => 30, "rating" => 8.3, "summary" => "After Ted runs into an old flame, he talks to his future kids about how being in the right place at the right time can impact a person's life. Meanwhile, Barney celebrates his 200th female conquest.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/243995.jpg"),
        array("id" => "s4e23", "season" => 4, "number" => 23, "name" => "As Fast as She Can", "airdate" => "11 May 2009", "runtime" => 30, "rating" => 8.1, "summary" => "In his attempt to assuage his guilt for \"ruining Ted's life,\" Tony, Stella's fiancé, insists on helping Ted find a job, but only manages to prove that no good deed goes unpunished. Meanwhile, Barney tries to prove he can get out of a speeding ticket.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/97/244003.jpg"),
