        array("id" => "s5e15", "season" => 5, "number" => 15, "name" => "Rabbit or Duck", "airdate" => "8 Feb 2010", "runtime" => 30, "rating" => 7.6, "summary" => "When Lily and Marshall forget to fix up Ted on a blind date for Valentine's Day, they use one of Barney's many discarded girls to see if they may become Ted's future wife. Meanwhile, Robin's obnoxious colleague invites her to a party at his apartment.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245459.jpg"),
