        array("id" => "s5e19", "season" => 5, "number" => 19, "name" => "Zoo or False", "airdate" => "12 Apr 2010", "runtime" => 30, "rating" => 7.3, "summary" => "When Marshall gets mugged, Lily decides she wants to get a gun for protection, so Marshall comes up with a convoluted story about the mugging to deter Lily from following through.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245473.jpg"),
        array("id" => "s5e20", "season" => 5, "number" => 20, "name" => "Home Wreckers", "airdate" => "19 Apr 2010", "runtime" => 30, "rating" => 7.7, "summary" => "When Ted attends his mother's wedding, he is extremely disturbed by her overly affectionate relationship with her fiancé, which forces him to think about his own life and make an impulsive decision.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245474.jpg"),
        array("id" => "s5e21", "season" => 5, "number" => 21, "name" => "Twin Beds", "airdate" => "3 May 2010", "runtime" => 30, "rating" => 7.8, "summary" => "When Ted and Barney jeopardize Robin's new relationship by professing their love for her, Robin realizes that she is finally over them. Meanwhile, after spending a weekend sleeping in twin beds, Marshall and Lily decide to get twin beds at home.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245499.jpg"),
        array("id" => "s5e22", "season" => 5, "number" => 22, "name" => "Robots vs. Wrestlers", "airdate" => "10 May 2010", "runtime" => 30, "rating" => 8.1, "summary" => "When Ted, Marshall, Lily and Barney crash a highfalutin party at a swanky New York apartment, Ted gets the chance to mingle with the snooty guests and show off his intellectual side.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245955.jpg"),
        array("id" => "s5e23", "season" => 5, "number" => 23, "name" => "The Wedding Bride", "airdate" => "17 May 2010", "runtime" => 30, "rating" => 8.1, "summary" => "When Ted takes a date to see a new hit movie, \"The Wedding Bride,\" he is shocked to learn the story is loosely based on his life, and that it was written by Tony, the man Stella left him for at the altar.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245963.jpg"),
        array("id" => "s5e24", "season" => 5, "number" => 24, "name" => "Doppelgangers", "airdate" => "24 May 2010", "runtime" => 30, "rating" => 8.3, "summary" => "Marshall and Lily make a secret pact to start trying to have a baby if they ever finally see Barney's doppelganger. Meanwhile, Robin finally gets an offer for her dream job.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/245978.jpg"),
