    array("number" => 6, "name" => "Season 6", "rating" => 7.8, "episodes" => array(
        array("id" => "s6e1", "season" => 6, "number" => 1, "name" => "Big Days", "airdate" => "20 Sep 2010", "runtime" => 30, "rating" => 7.7, "summary" => "When Ted and Barney argue about who has \"dibs\" on a hot girl, Ted realizes that she is there with Cindy, a girl he previously dated who is also the roommate of his future wife. Meanwhile, Robin is heartbroken over Don, and Marshall can't keep quiet about his…", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/246018.jpg"),
        array("id" => "s6e2", "season" => 6, "number" => 2, "name" => "Cleaning House", "airdate" => "27 Sep 2010", "runtime" => 30, "rating" => 7.8, "summary" => "When Barney convinces the gang to help his mom move out of her home, they quickly learn that she has been very protective of Barney and lied to him about events throughout his life. Meanwhile, Ted gets upset when Robin oversells him to a blind date.", "image" => "https://static.tvmaze.com/uploads/images/medium_landscape/98/246021.jpg"),
